{
  "operations": [
    {
      "op": "update",
      "collection": "processes",
      "target_id": "proc_microtubule_track_provision",
      "fields": {
        "scientific_name": "Microtubule track provision for vesicle movement",
        "action_category": "interaction",
        "participants": [
          {"role": "track_provider", "entity_ref": "ent_microtubule"},
          {"role": "cargo_guided", "entity_ref": "ent_vesicle"}
        ],
        "input_roles": ["track_provider", "cargo_guided"],
        "output_roles": ["track_provider", "cargo_guided"],
        "preconditions": {"microtubule_present": true},
        "effects": {"vesicle_can_move_along_microtubule": true},
        "temporal_scope": {
          "start_condition": "Microtubule is present and vesicle movement along it begins.",
          "end_condition": "Vesicle movement along the microtubule ceases or the microtubule is no longer available as a track.",
          "concurrent_with": ["proc_vesicle_transport_along_microtubule"],
          "after": []
        },
        "observables": [
          {
            "constraint_id": "obs_track_relation_during_transport",
            "predicate": "relation_holds_during",
            "relation_ref": "rel_microtubule_track_for_vesicle",
            "source_role": "track_provider",
            "target_role": "cargo_guided",
            "capability": "DETERMINISTIC",
            "evidence_ids": ["E_9af4c0e6bde1"],
            "support": [
              {"evidence_id": "E_9af4c0e6bde1", "quote": "provide a track along which vesicles move through the cell", "location": "paragraph_12"}
            ]
          }
        ],
        "evidence_ids": ["E_9af4c0e6bde1"],
        "support": [
          {"evidence_id": "E_9af4c0e6bde1", "quote": "They help the cell resist compression, provide a track along which vesicles move through the cell, and pull replicated chromosomes to opposite ends of a dividing cell.", "location": "paragraph_12"}
        ],
        "exceptions": [
          {
            "exception_id": "exc_track_absent",
            "description": "If microtubules are not present or not serving as tracks, this provision does not hold.",
            "evidence_ids": ["E_9af4c0e6bde1"]
          }
        ],
        "precondition_state_refs": ["st_microtubule_present"],
        "effect_state_refs": ["st_microtubule_available_as_track"]
      }
    },
    {
      "op": "update",
      "collection": "processes",
      "target_id": "proc_vesicle_transport_along_microtubule",
      "fields": {
        "scientific_name": "Vesicle transport along microtubules",
        "action_category": "transport",
        "participants": [
          {"role": "cargo", "entity_ref": "ent_vesicle"},
          {"role": "track", "entity_ref": "ent_microtubule"}
        ],
        "input_roles": ["cargo", "track"],
        "output_roles": ["cargo", "track"],
        "preconditions": {"microtubule_present_as_track": true, "vesicle_present": true},
        "effects": {"vesicle_moves_through_cell": true},
        "temporal_scope": {
          "start_condition": "Vesicle movement along a microtubule track begins.",
          "end_condition": "Vesicle movement along the microtubule track ends.",
          "concurrent_with": ["proc_microtubule_track_provision"],
          "after": []
        },
        "observables": [
          {
            "constraint_id": "obs_vesicle_transport_relation",
            "predicate": "relation_holds_during",
            "relation_ref": "rel_microtubule_track_for_vesicle",
            "source_role": "track",
            "target_role": "cargo",
            "capability": "DETERMINISTIC",
            "evidence_ids": ["E_9af4c0e6bde1"],
            "support": [
              {"evidence_id": "E_9af4c0e6bde1", "quote": "provide a track along which vesicles move through the cell", "location": "paragraph_12"}
            ]
          }
        ],
        "evidence_ids": ["E_9af4c0e6bde1"],
        "support": [
          {"evidence_id": "E_9af4c0e6bde1", "quote": "provide a track along which vesicles move through the cell", "location": "paragraph_12"},
          {"evidence_id": "E_9af4c0e6bde1", "quote": "allow cytoplasm and vesicles to move within the cell", "location": "paragraph_1"}
        ],
        "exceptions": [
          {
            "exception_id": "exc_no_track",
            "description": "Vesicle transport along microtubules does not occur if no microtubule track is available.",
            "evidence_ids": ["E_9af4c0e6bde1"]
          }
        ],
        "precondition_state_refs": ["st_microtubule_available_as_track", "st_vesicle_present"],
        "effect_state_refs": ["st_vesicle_moving_along_microtubule"]
      }
    }
  ],
  "state_upgrade": {
    "schema_version": "1.1",
    "clip_start": {
      "stage": "Steady-state eukaryotic cell in which microtubules are present as tracks and vesicles are present as cargo for movement along those tracks.",
      "existing_entity_refs": ["ent_cytoskeleton", "ent_microtubule", "ent_vesicle"],
      "omitted_processes": [
        {
          "description": "Microtubule assembly and disassembly dynamics",
          "reason": "Retrieved evidence notes that microtubules can disassemble and reform quickly, but the requested teaching scope is vesicle transport along microtubules, not microtubule dynamics.",
          "required_by_task": false
        },
        {
          "description": "Vesicle cargo selection and membrane fusion",
          "reason": "The retrieved passages do not describe vesicle cargo selection or fusion mechanisms; these are outside the stated scope.",
          "required_by_task": false
        },
        {
          "description": "Motor-protein identity and detailed mechanochemical stepping cycle",
          "reason": "The retrieved evidence E_9af4c0e6bde1 states that microtubules provide a track along which vesicles move but does not name or mechanistically describe motor proteins for vesicle transport; motor-protein-dependent details are therefore outside the supported scope of this model.",
          "required_by_task": false
        }
      ]
    },
    "states": [
      {
        "state_id": "st_microtubule_present",
