        "producer_process_id": null,
        "required_by_process_ids": ["proc_vesicle_transport_along_microtubule"],
        "evidence_ids": ["E_9af4c0e6bde1"],
        "support": [
          {"evidence_id": "E_9af4c0e6bde1", "quote": "provide a track along which vesicles move through the cell", "location": "paragraph_12"}
        ]
      },
      {
        "state_id": "st_vesicle_moving_along_microtubule",
        "subject_ref": "ent_vesicle",
        "property": "moving_along_microtubule",
        "value": true,
        "state_kind": "PRODUCED_STATE",
        "scope": {"process_ids": ["proc_vesicle_transport_along_microtubule"]},
        "producer_process_id": "proc_vesicle_transport_along_microtubule",
        "required_by_process_ids": [],
        "evidence_ids": ["E_9af4c0e6bde1"],
        "support": [
          {"evidence_id": "E_9af4c0e6bde1", "quote": "provide a track along which vesicles move through the cell", "location": "paragraph_12"},
          {"evidence_id": "E_9af4c0e6bde1", "quote": "allow cytoplasm and vesicles to move within the cell", "location": "paragraph_1"}
        ]
      }
    ]
  },
  "issue_resolution": [
    {
      "issue_id": "ISS-001",
      "changed_target_ids": ["proc_vesicle_transport_along_microtubule", "proc_microtubule_track_provision"],
      "reason": "Reverted to the original source-supported framing: E_9af4c0e6bde1 states microtubules provide a track along which vesicles move, but does not name or describe motor proteins mediating vesicle transport. Motor-protein-dependent claims are left unresolved rather than asserted.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "ISS-002",
      "changed_target_ids": ["proc_vesicle_transport_along_microtubule", "ent_vesicle", "rel_microtubule_track_for_vesicle"],
      "reason": "Removed the motor-protein-mediated causal chain and motor-cargo binding process because the retrieved evidence does not support motor proteins as actors in vesicle-specific transport; E_9af4c0e6bde1 supports only that vesicles move along microtubule tracks.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "ISS-003",
      "changed_target_ids": ["proc_vesicle_transport_along_microtubule"],
      "reason": "The observable obs_vesicle_transport_relation now uses only the source-supported relation (rel_microtubule_track_for_vesicle) with DETERMINISTIC capability, directly quoting E_9af4c0e6bde1 on vesicles moving along microtubule tracks.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "ISS-004",
      "changed_target_ids": ["proc_microtubule_track_provision"],
      "reason": "Track provision is reframed as the source-supported structural/interaction process: microtubules provide a track for vesicle movement, with start/end tied to vesicle movement; no unsupported motor-protein requirement is retained. E_9af4c0e6bde1 does not describe track provision as an active microtubule process, so this remains a teaching simplification.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "ISS-005",
      "changed_target_ids": ["ent_vesicle"],
      "reason": "Vesicle states are limited to moving_along_microtubule and stationary, supported by E_9af4c0e6bde1; unsupported motor-bound state removed.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "ISS-006",
      "changed_target_ids": ["proc_vesicle_transport_along_microtubule", "proc_microtubule_track_provision"],
      "reason": "Model content now matches the supported scope of E_9af4c0e6bde1 (microtubule tracks for vesicle movement) and does not assert motor-protein-dependent mechanisms that the evidence does not support; this limitation is recorded in unresolved_questions.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "ISS-007",
      "changed_target_ids": [],
      "reason": "Directionality, motor protein identity (kinesin/dynein), and organism specificity remain unresolved because the retrieved evidence E_9af4c0e6bde1 does not specify them; no unsupported claims added.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    },
    {
      "issue_id": "STATE_MODEL_MIGRATION",
      "changed_target_ids": ["proc_microtubule_track_provision", "proc_vesicle_transport_along_microtubule", "st_microtubule_present", "st_microtubule_available_as_track", "st_vesicle_present", "st_vesicle_moving_along_microtubule"],
      "reason": "Migrated to typed state model: initial conditions are microtubule present as track and vesicle present; track provision produces microtubule available as track; transport requires available track and vesicle present and produces vesicle moving along microtubule. All states supported by E_9af4c0e6bde1. No unsupported motor-protein states retained.",
      "evidence_ids": ["E_9af4c0e6bde1"]
    }
  ]
}
